architecture.h4_f:
pesan = CBOR{v:1, teks, balasan_ke, terkirim_at}
ct = AES-GCM-256-Enkripsi(k, nonce, pesan, aad=room_id)
POST /api/rooms/{id}/messages {teks sandi: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, teks, reply_to?, thread_id?, mention?, sent_at}
ct = AES-GCM-256-Enkripsi(room_key, nonce, pt, aad=hex(room_id))
kawat = CBOR{
  v: 1,
  ciphertext: hex(ct), // panjang variabel
  nonce: heksa(12 B),
  pengirim_semu: hex(16 B),
  terkirim_at: unix_ms
}

cryptoWire.h5_f:
luar = CBOR{
  source_node: hex32,
  target_pengguna: int64,
  inner_ciphertext: byte,
  inner_nonce: byte,
  terkirim_at: unix_ms
}
sig = Ed25519-Sign(source_priv, luar)
POST /federation/deliver { amplop: luar, tanda: hex64 }

auth.h1_f:
POST /api/authentication/register
  { nama pengguna, kata sandi, x25519_public_key, nama_tampilan, telepon?, email?, avatar_emoji }

Respons 201 Dibuat:
  { access_token, refresh_token, user_id, nama pengguna, ... }

auth.h3_f:
muatan access_token:
  { sub: user_id, jti: device_id, ketik: "akses", exp: sekarang + 15 menit }
muatan refresh_token:
  { sub: user_id, jti: device_id, ketik: "refresh", exp: sekarang + 30d }

HS256-ditandatangani dengan rahasia 64-byte node dari .env

auth.h4_f:
register_begin(): tantangan = Rand(32)
                    pilihan = { rp.id, user.id, pubKeyCredParams, tantangan }
                    opsi pengembalian

register_finish(pengesahan):
  verifikasi pengesahan terhadap TPM / akar Enklave Aman CA
  toko { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: heksa 128-bit, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verifikasi { nonce }
  → perangkat baru terdaftar; JWT kembali.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Enkripsi(room_key, nonce, CBOR_payload, aad=room_id)

Bingkai penyebaran: { ketik:"m", ruangan, pesan:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {nama file, ukuran, chunk_size_hint}
            ← {upload_id, potongan_ukuran}
potongan PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
selesaikan POST /api/files/resumable/{upload_id}/finalisasi {plain_blake3}
            ← 201 {file_id, url}
TTL yang belum selesai: 24 jam

files.h4_f:
daftar_tolak = {
  "aplikasi/x-dosexec",
  "aplikasi/x-sharedlib",
  "aplikasi/x-mach-biner",
}
jika magic.from_buffer(buf[:1024]) di reject_list: kembalikan 415

presence.h1_f:
klien: pada penekanan tombol pertama → kirim {type:"t", state:"start"}
         tidak ada lagi pengiriman selama 3 detik kecuali status berubah
         10 detik setelah penekanan tombol terakhir → kirim {type:"t", state:"stop"}
penerima: berhenti otomatis 10 detik setelah "mulai" terakhir jika tidak ada "berhenti" yang tiba

calls.h1_f:
POST /api/calls/{room_id}/mulai {video, audio} → call_id
WS siaran {type:"c", jenis:"invite", call_id}
WS siaran {type:"c", jenis:"offer", sdp}
WS siaran {tipe:"c", jenis:"jawaban", sdp}
WS siaran {tipe:"c", jenis:"kandidat",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
amplop = {
  source_node : hex32,
  target_pengguna : int64,
  inner_ciphertext: byte,
  inner_nonce : byte,
  terkirim_at : unix_ms,
}
sig = Ed25519Tanda(source_priv, CBOR(amplop))
POST /federasi/pengiriman { amplop, tanda tangan }

gossip.h3_f:
iklan = {kunci pub, titik akhir, diiklankan_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(iklan))
muatan gosip: [..., {ad, sig}, ...]

penerima: verifikasi tanda terhadap ad.pubkey → simpan jika oke
tambahan: PoW dengan 2^18 angka nol di depan pada {pubkey, endpoint}

stealth.h2_f:
ClientHello byte = chrome_120_template dengan {
  acak = acak kami,
  server_name = nama host kami (atau dibungkus ECH),
  session_id = id sesi kami,
}
JA4 = t13d_xxxx_xxxx_xxxx (cocok dengan stabil Chrome saat ini)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nama: x.vortexx.sol}
ECH: ClientHello.extensions += terenkripsi_sni(kunci_publik_dari_HTTPS_record)
DGA: domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(permintaan) { dekripsi(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { dekripsi(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
alat = alat_tanda
input = pohon sumber, kunci/rilis.kunci
manifes = {
  versi: "0.1.0",
  built_at: unix_ms,
  file: [{jalur, sha256, ukuran}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, ditandatangani_oleh: pub_hex, sig: sig_hex}

bots.h1_f:
buat: POST /api/bots {nama pengguna, nama_tampilan, kode}
          → {bot_id, token, kunci pub}
jalankan: dalam proses (coroutine di dalam node)
      OR eksternal (jajak pendapat panjang /api/bots/{id}/updates, token-auth'd)
pesan: {teks, tanda tangan: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
pada / mulai {
  memancarkan "Selamat datang, {ctx.first_name}"
}
pada /tambahkan <barang> {
  state.list = (state.list atau []) + [ctx.args.item]
  emit "Ditambahkan: {ctx.args.item}"
}

security.h4_f:
canary.txt (setiap hari):
  {tanggal, tanda: Ed25519-Sign(rilis_priv, tanggal)}
klien memverifikasi → tidak ada atau tidak valid ⇒ diduga ada kompromi

darurat:
  admin POST /api/admin/cabut-semua {alasan}
  node menyiarkan {type:"n", event:"compromise", Reason}
  klien menghapus kunci, memaksa bootstrap ulang

debugging.h2_f:
histogram laju (per rute + metode):
  pusaran_http_requests_total{rute,metode,status}
  pusaran_http_request_duration_seconds_bucket{rute,metode,le}

pengukur soket web:
  pusaran_ws_koneksi{node}
  pusaran_ws_fanout_queue_kedalaman{ruangan,pengguna}

penghitung khusus:
  pusaran_pesan_terkirim_total{tipe_kamar}
  pusaran_panggilan_mulai_total{jenis}

login.h3_f:
{
  "nama pengguna": "alice",
  "password": "pokok baterai kuda yang benar",
  "totp": "123456" // diperlukan jika 2FA diaktifkan
}

login.h4_f:
jika berhasil: 201 + JWT amplop (bentuknya sama dengan register)
pada 2FA dibutuhkan: 200 { "needs_2fa": true } (belum ada JWT)
jika gagal: 401 { "error":"invalid_credentials" }

apns.h1_f:
POST https://api.push.apple.com/3/device/<device_token>
Header: apns-topic: <bundle_id>, apns-push-type: alert, apns-collapse-id: room:42
Isi: {aps: {peringatan: {judul, isi}}, data: <disegel>}

bmp.h1_f:
mailbox_id = HKDF(recipient_pubkey, info="bmp-v1", len=32)
Setoran: POST /bmp/deposit {mailbox_id, gumpalan ≤1MB}
Pengambilan: GET /bmp/messages (diautentikasi)

controller.h1_f:
GET /v1/integrity → {status, ditandatangani_oleh, cocok, tidak cocok, …}
GET /v1/kesehatan → {status, versi, kunci pub, statistik}
GET /v1/entri → [{protokol, url}, …]
GET /v1/cermin → [controller_url, …]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Otorisasi: Pembawa <oauth2_token>
Isi: {pesan: {token: <perangkat>, data: {...disegel...}, android: {collapse_key}}}

federation.h1_f:
amplop = {source_node, target_user, inner_ct, inner_nonce, sent_at}
sig = Ed25519-Sign(source_priv, CBOR(amplop))
POST /federasi/kirim {amplop, tanda tangan}
B memverifikasi: menandatangani federasi[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE pesan_fts USING fts5(
  konten, -- kolom yang diberi token
  kamar_id UNINDEXED,
  tokenize = 'unicode61 hapus_diakritik 2'
);
pertanyaan: SELECT rowid FROM messages_fts WHERE konten MATCH 'foo'

gravitix.h1_f:
di /mulai { emit "Selamat datang, {ctx.first_name}" }
pada /tambahkan <barang> {
  state.list = (state.list atau []) + [ctx.args.item]
  emit "Ditambahkan: {ctx.args.item}"
}

prekey.h1_f:
bundel = {
  identitas_pk,
  ditandatangani_prekey_pk,
  ditandatangani_prekey_sig = Ed25519-Tanda(identitas_priv, ditandatangani_prekey_pk),
  one_time_prekeys: [pk_0, pk_1, ..., pk_9]
}

vapid.h1_f:
VAPID kunci: pasangan kunci Ed25519 per node
tanda tangan JWT: {aud: push_service_origin, exp: sekarang + 12 jam, sub: mailto:ops@example}
header permintaan push: Otorisasi: vapid t=<jwt>, k=<vapid_public_key>
